<script setup lang="ts">
import { computed, onMounted, reactive, ref } from "vue";
import { Check, Database as DatabaseIcon, LoaderCircle, Pencil, Plus, RefreshCw, ShieldCheck, Trash2, X } from "lucide-vue-next";
import { ApiRequestError, createDatabase, deleteDatabase, fetchDatabaseConfigs, testDatabase, updateDatabase, updateDatabaseTableAccess } from "@/api/client";
import { getDemoRole } from "@/auth/auth";
import type { Database, DatabaseDialect } from "@/types/api";

const databases = ref<Database[]>([]);
const loading = ref(true);
const saving = ref(false);
const testingId = ref("");
const errorMessage = ref("");
const modalOpen = ref(false);
const editingDatabase = ref<Database | null>(null);
const isAdmin = computed(() => getDemoRole() === "super_admin");
const form = reactive({ name: "", dialect: "sqlite" as DatabaseDialect, path: "data/demo.sqlite", host: "", port: "3306", database: "", username: "", credentialRef: "", tls: true });
const enabledTableCount = computed(() => databases.value.reduce((count, database) => count + database.tables.filter((table) => table.agent_access).length, 0));

function setError(error: unknown, fallback: string) { errorMessage.value = error instanceof ApiRequestError ? error.message : fallback; }
async function loadDatabases() { loading.value = true; errorMessage.value = ""; try { databases.value = await fetchDatabaseConfigs(); } catch (error) { setError(error, "数据库列表加载失败。"); } finally { loading.value = false; } }
function resetForm() { Object.assign(form, { name: "", dialect: "sqlite", path: "data/demo.sqlite", host: "", port: "3306", database: "", username: "", credentialRef: "", tls: true }); }
function openCreate() { editingDatabase.value = null; resetForm(); errorMessage.value = ""; modalOpen.value = true; }
function openEdit(database: Database) { editingDatabase.value = database; Object.assign(form, { name: database.name, dialect: database.dialect, path: String(database.config.path || ""), host: String(database.config.host || ""), port: String(database.config.port || "3306"), database: String(database.config.database || ""), username: String(database.config.username || ""), credentialRef: String(database.config.credential_ref || ""), tls: database.config.tls !== false }); errorMessage.value = ""; modalOpen.value = true; }
function closeModal() { if (!saving.value) modalOpen.value = false; }
function configPayload() { if (form.dialect === "sqlite") return { path: form.path.trim() }; return { host: form.host.trim(), port: Number(form.port), database: form.database.trim(), username: form.username.trim(), credential_ref: form.credentialRef.trim(), tls: form.tls }; }
async function saveDatabase() {
  if (!form.name.trim()) { errorMessage.value = "请输入数据库名称。"; return; }
  if (form.dialect === "sqlite" && !form.path.trim()) { errorMessage.value = "请输入 SQLite 文件路径。"; return; }
  if (form.dialect === "mysql" && (!form.host.trim() || !form.database.trim() || !form.username.trim() || !form.credentialRef.trim())) { errorMessage.value = "请完整填写 MySQL 连接信息和凭据引用。"; return; }
  saving.value = true; errorMessage.value = "";
  try { const saved = editingDatabase.value ? await updateDatabase(editingDatabase.value.id, { name: form.name.trim(), config: configPayload() }) : await createDatabase({ name: form.name.trim(), dialect: form.dialect, config: configPayload() }); const index = databases.value.findIndex((database) => database.id === saved.id); if (index === -1) databases.value.push(saved); else databases.value[index] = saved; modalOpen.value = false; } catch (error) { setError(error, "数据库保存失败。"); } finally { saving.value = false; }
}
async function handleTest(database: Database) { testingId.value = database.id; errorMessage.value = ""; try { const refreshed = await testDatabase(database.id); const index = databases.value.findIndex((item) => item.id === database.id); if (index !== -1) databases.value[index] = refreshed; } catch (error) { setError(error, "连接测试失败。"); } finally { testingId.value = ""; } }
async function toggleTable(database: Database, tableName: string, value: boolean) { const table = database.tables.find((item) => item.table_name === tableName); if (!table || !isAdmin.value) return; const previous = table.agent_access; table.agent_access = value; try { const saved = await updateDatabaseTableAccess(database.id, tableName, value); table.agent_access = saved.agent_access; } catch (error) { table.agent_access = previous; setError(error, "表权限更新失败。"); } }
async function removeDatabase(database: Database) { if (database.id === "demo" || !window.confirm(`确定删除“${database.name}”吗？`)) return; try { await deleteDatabase(database.id); databases.value = databases.value.filter((item) => item.id !== database.id); } catch (error) { setError(error, "数据库删除失败。"); } }
onMounted(() => void loadDatabases());
</script>

<template>
  <main class="databases-page">
    <header class="page-header"><div><p class="eyebrow">DATA SOURCES</p><h1>数据库</h1><p class="page-description">管理数据源，并控制 Agent 可访问的数据表。</p></div><button v-if="isAdmin" class="primary-button" type="button" @click="openCreate"><Plus :size="17" /> 添加数据库</button></header>
    <section class="summary-row" aria-label="数据库概览"><div class="summary-item"><strong>{{ databases.length }}</strong><span>数据源</span></div><div class="summary-item"><strong>{{ enabledTableCount }}</strong><span>Agent 已授权表</span></div><div class="summary-item"><strong><ShieldCheck :size="18" /> 只读</strong><span>查询策略</span></div></section>
    <p v-if="errorMessage && !modalOpen" class="alert" role="alert">{{ errorMessage }}</p>
    <section class="database-surface" aria-labelledby="database-list-title">
      <div class="surface-heading"><div><h2 id="database-list-title">数据源列表</h2><p>只有开启的表会进入 Agent 的 Schema 和查询权限。</p></div><button class="icon-button" type="button" title="刷新列表" aria-label="刷新列表" :disabled="loading" @click="loadDatabases"><RefreshCw :class="{ spin: loading }" :size="17" /></button></div>
      <div v-if="loading" class="empty-state"><LoaderCircle class="spin" :size="22" />正在加载数据库</div><div v-else-if="databases.length === 0" class="empty-state"><DatabaseIcon :size="22" />暂无数据库</div>
      <div v-else class="database-list"><article v-for="database in databases" :key="database.id" class="database-card">
        <div class="database-card__top"><div class="database-identity"><span class="database-icon"><DatabaseIcon :size="19" /></span><div><h3>{{ database.name }}</h3><span class="database-meta">{{ database.id }} · {{ database.dialect.toUpperCase() }}</span></div></div><span :class="['status-badge', database.enabled ? 'status-badge--ready' : '']"><Check v-if="database.enabled" :size="13" />{{ database.enabled ? "已启用" : "已停用" }}</span></div>
        <div class="database-card__body"><div class="table-heading"><strong>Agent 表权限</strong><span>{{ database.tables.filter((table) => table.agent_access).length }} / {{ database.tables.length }} 已授权</span></div><div v-if="database.tables.length" class="table-list"><label v-for="table in database.tables" :key="table.table_name" class="table-row"><span><span class="table-name">{{ table.table_name }}</span><small>{{ table.agent_access ? "允许查询" : "已禁止" }}</small></span><input type="checkbox" :checked="table.agent_access" :disabled="!isAdmin" @change="toggleTable(database, table.table_name, ($event.target as HTMLInputElement).checked)" /></label></div><div v-else class="table-empty">请先测试连接以读取数据表</div></div>
        <footer class="database-card__actions"><button class="secondary-button" type="button" :disabled="!isAdmin || testingId === database.id" @click="handleTest(database)"><LoaderCircle v-if="testingId === database.id" class="spin" :size="15" /><RefreshCw v-else :size="15" />{{ testingId === database.id ? "测试中" : "测试连接" }}</button><div v-if="isAdmin" class="action-group"><button class="icon-button" type="button" title="编辑数据库" aria-label="编辑数据库" @click="openEdit(database)"><Pencil :size="16" /></button><button v-if="database.id !== 'demo'" class="icon-button icon-button--danger" type="button" title="删除数据库" aria-label="删除数据库" @click="removeDatabase(database)"><Trash2 :size="16" /></button></div></footer>
      </article></div>
    </section>
    <div v-if="modalOpen" class="modal-backdrop" role="presentation" @click.self="closeModal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="database-modal-title"><header class="modal-header"><div><p class="eyebrow">{{ editingDatabase ? "EDIT SOURCE" : "NEW SOURCE" }}</p><h2 id="database-modal-title">{{ editingDatabase ? "编辑数据库" : "添加数据库" }}</h2></div><button class="icon-button" type="button" title="关闭" aria-label="关闭" @click="closeModal"><X :size="19" /></button></header><form class="database-form" @submit.prevent="saveDatabase"><label>名称<input v-model="form.name" type="text" maxlength="100" :disabled="saving" /></label><fieldset><legend>类型</legend><div class="dialect-switch"><button type="button" :class="{ active: form.dialect === 'sqlite' }" @click="form.dialect = 'sqlite'">SQLite</button><button type="button" :class="{ active: form.dialect === 'mysql' }" @click="form.dialect = 'mysql'">MySQL</button></div></fieldset><label v-if="form.dialect === 'sqlite'">文件路径<input v-model="form.path" type="text" placeholder="data/demo.sqlite" :disabled="saving" /></label><template v-else><label>主机<input v-model="form.host" type="text" placeholder="127.0.0.1" :disabled="saving" /></label><div class="form-grid"><label>端口<input v-model="form.port" type="number" min="1" max="65535" :disabled="saving" /></label><label>数据库名<input v-model="form.database" type="text" :disabled="saving" /></label></div><label>用户名<input v-model="form.username" type="text" :disabled="saving" /></label><label>凭据引用<input v-model="form.credentialRef" type="text" placeholder="secret/my-db-readonly" :disabled="saving" /></label><label class="checkbox-line"><input v-model="form.tls" type="checkbox" :disabled="saving" />启用 TLS</label></template><p v-if="errorMessage && modalOpen" class="form-error" role="alert">{{ errorMessage }}</p><footer class="modal-actions"><button class="secondary-button" type="button" :disabled="saving" @click="closeModal">取消</button><button class="primary-button" type="submit" :disabled="saving"><LoaderCircle v-if="saving" class="spin" :size="16" />{{ saving ? "保存中" : "保存数据库" }}</button></footer></form></section></div>
  </main>
</template>

<style scoped>
.databases-page{min-height:100vh;padding:30px clamp(20px,5vw,72px);color:#203027;background:#f7f9f7}.page-header,.surface-heading,.database-card__top,.database-card__actions,.modal-header,.modal-actions,.table-heading{display:flex;align-items:center;justify-content:space-between;gap:18px}.page-header{align-items:flex-end;margin-bottom:28px}.eyebrow{margin:0 0 9px;color:#4c9065;font-size:10px;font-weight:800;letter-spacing:.14em}h1,h2,h3,p{margin-top:0}h1{margin-bottom:8px;font-size:30px}h2{margin-bottom:0;font-size:18px}.page-description,.surface-heading p{margin-bottom:0;color:#718077;font-size:13px}.primary-button,.secondary-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:40px;border-radius:7px;padding:0 14px;font-size:13px;font-weight:750;cursor:pointer}.primary-button{border:0;color:#143322;background:#b7e7cb}.primary-button:hover{background:#a6dbb9}.primary-button:disabled,.secondary-button:disabled{opacity:.55;cursor:default}.secondary-button{border:1px solid #d9e0db;color:#55645b;background:#fff}.secondary-button:hover:not(:disabled){border-color:#b6cebd;color:#326d4c}.summary-row{display:flex;gap:1px;margin-bottom:20px;border:1px solid #e0e7e2;background:#e0e7e2}.summary-item{display:grid;flex:1;gap:6px;padding:17px 21px;background:#fff}.summary-item strong{display:inline-flex;align-items:center;gap:5px;font-size:21px}.summary-item span{color:#7d8a82;font-size:11px}.alert,.form-error{margin:16px 0;border:1px solid #f0c8c8;border-radius:6px;padding:11px 13px;color:#a24a4a;background:#fff7f7;font-size:13px}.form-error{margin:0}.database-surface{border:1px solid #e0e7e2;background:#fff}.surface-heading{padding:21px 24px;border-bottom:1px solid #edf0ed}.database-list{display:grid;gap:14px;padding:18px 24px 24px}.database-card{border:1px solid #e0e7e2;border-radius:8px;background:#fff}.database-card__top{padding:19px 21px;border-bottom:1px solid #edf0ed}.database-identity{display:flex;min-width:0;align-items:center;gap:11px}.database-icon{display:grid;width:36px;height:36px;place-items:center;border-radius:8px;color:#397453;background:#e8f4eb}.database-identity h3{margin-bottom:5px;font-size:15px}.database-meta{color:#8a968e;font-size:11px}.status-badge{display:inline-flex;align-items:center;gap:5px;border-radius:999px;padding:5px 9px;color:#9a6e34;background:#fff4df;font-size:11px;font-weight:700}.status-badge--ready{color:#397453;background:#e8f4eb}.database-card__body{padding:17px 21px 8px}.table-heading{margin-bottom:10px;color:#4b5e51;font-size:12px}.table-heading span{color:#8a968e;font-size:11px}.table-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px 12px}.table-row{display:flex;min-height:45px;align-items:center;justify-content:space-between;gap:12px;border:1px solid #edf0ed;border-radius:6px;padding:7px 11px;cursor:pointer}.table-row:hover{border-color:#c8dbcd;background:#fbfefb}.table-row>span{display:grid;gap:2px;min-width:0}.table-name{overflow:hidden;color:#304337;font:12px ui-monospace,SFMono-Regular,Consolas,monospace;text-overflow:ellipsis;white-space:nowrap}.table-row small{color:#9aa49e;font-size:10px}.table-row input,.checkbox-line input{width:16px;height:16px;accent-color:#4b9a67}.table-empty{padding:10px 0;color:#9aa49e;font-size:12px}.database-card__actions{min-height:59px;border-top:1px solid #edf0ed;padding:10px 21px}.action-group{display:flex;gap:4px}.icon-button{display:inline-grid;width:32px;height:32px;place-items:center;border:0;border-radius:6px;color:#64736a;background:transparent;cursor:pointer}.icon-button:hover:not(:disabled){color:#326d4c;background:#eef5ef}.icon-button--danger:hover{color:#b65353;background:#fff0f0}.empty-state{display:flex;min-height:190px;align-items:center;justify-content:center;gap:9px;color:#7b887f;font-size:13px}.spin{animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.modal-backdrop{position:fixed;z-index:100;inset:0;display:grid;place-items:center;padding:24px;background:rgba(22,37,29,.35)}.modal{width:min(100%,470px);max-height:min(90vh,700px);overflow:auto;border:1px solid #dfe7e1;border-radius:9px;padding:24px;background:#fff;box-shadow:0 24px 70px rgba(22,37,29,.22)}.modal-header{align-items:flex-start;margin-bottom:23px}.database-form{display:grid;gap:15px}.database-form label,fieldset{display:grid;gap:7px;border:0;padding:0;color:#4a5b50;font-size:12px;font-weight:700}.database-form input[type=text],.database-form input[type=number]{width:100%;height:41px;border:1px solid #d9e2db;border-radius:6px;padding:0 10px;color:#26382c;outline:0;background:#fbfdfb;font-size:13px}.database-form input:focus{border-color:#78b58b;box-shadow:0 0 0 3px rgba(104,181,130,.12)}.database-form legend{margin-bottom:7px;color:#4a5b50;font-size:12px;font-weight:700}.dialect-switch{display:grid;grid-template-columns:1fr 1fr;gap:1px;border:1px solid #d9e2db;border-radius:6px;padding:2px;background:#eef2ef}.dialect-switch button{min-height:35px;border:0;border-radius:4px;color:#718077;background:transparent;cursor:pointer;font-size:12px;font-weight:700}.dialect-switch button.active{color:#245e3c;background:#fff;box-shadow:0 1px 4px rgba(35,76,49,.1)}.form-grid{display:grid;grid-template-columns:1fr 1.5fr;gap:12px}.checkbox-line{display:flex!important;align-items:center;gap:8px!important;font-weight:500!important}.modal-actions{justify-content:flex-end;margin-top:4px}@media(max-width:680px){.databases-page{padding:22px 16px}.page-header{align-items:flex-start;flex-direction:column}.page-header .primary-button{width:100%}.summary-row{display:grid;grid-template-columns:1fr 1fr}.summary-item:last-child{grid-column:1/-1}.surface-heading{padding:18px}.database-list{padding:14px}.database-card__top,.database-card__body,.database-card__actions{padding-inline:16px}.table-list{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}}
</style>
